// Joins the migrations into one file that builds the whole database from nothing. Used to set up a
// NEW, EMPTY project (staging, a demo environment, a new region) with a single paste into the
// Supabase SQL editor, instead of running fifteen files in the right order by hand.
// Pure so it can be tested; scripts/build-schema.mjs reads the files and writes the result.

const HEADER = `-- CourseSync: complete database schema for a NEW, EMPTY Supabase project.
--
-- Generated by scripts/build-schema.mjs from the files in migrations/ (in order). Do not edit it
-- and do NOT run it on a project that already has CourseSync tables (such as production): it would
-- fail or duplicate things. Existing databases are upgraded with the individual migration files.
--
-- Run it once, in the Supabase SQL editor of the new project. If it stops with an error, fix the
-- cause and start again from an empty project; do not re-run it on top of a half-built one.
`

/**
 * @param files [{ name: '000_baseline.sql', sql: '...' }, ...] in any order
 * Rollback scripts must not be passed in (they live in migrations/rollback/).
 */
export function buildSchema(files) {
  if (files.length === 0) throw new Error('No migrations to build from')

  const sorted = [...files].sort((a, b) => a.name.localeCompare(b.name))
  const numbers = sorted.map(f => f.name.match(/^(\d{3})_/)?.[1])
  if (numbers.some(n => n === undefined)) {
    throw new Error(`Every migration must start with a three-digit number: ${sorted.filter((f, i) => numbers[i] === undefined).map(f => f.name).join(', ')}`)
  }
  if (new Set(numbers).size !== numbers.length) throw new Error('Two migrations share the same number')
  if (numbers[0] !== '000') throw new Error('The first migration must be 000_baseline.sql')
  for (let i = 1; i < numbers.length; i++) {
    if (Number(numbers[i]) !== Number(numbers[i - 1]) + 1) {
      throw new Error(`Migrations are not consecutive: ${sorted[i - 1].name} is followed by ${sorted[i].name}`)
    }
  }

  const parts = sorted.map(f => `-- ==================== ${f.name} ====================\n${f.sql.trim()}\n`)
  return `${HEADER}\n${parts.join('\n')}`
}
